function validate([words, k]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 500) return 'words needs 1 to 500 strings.';
  if (words.some(w => typeof w !== 'string' || !/^[a-z]{1,10}$/.test(w))) return 'Each word has 1 to 10 lowercase letters.';
  const distinct = new Set(words).size;
  if (!Number.isInteger(k) || k < 1 || k > distinct) return `k must be between 1 and the number of distinct words (${distinct}).`;
  return null;
}

