function topKFrequent(words, k) {
  const count = new Map();
  for (const word of words) {
    count.set(word, (count.get(word) || 0) + 1);
  }
  const worse = (a, b) => count.get(a) < count.get(b) || (count.get(a) === count.get(b) && a > b);
  const heap = [];
  const swap = (i, j) => { [heap[i], heap[j]] = [heap[j], heap[i]]; };
  const push = (word) => {
    heap.push(word);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (!worse(heap[i], heap[parent])) break;
      swap(i, parent);
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        const left = 2 * i + 1;
        const right = left + 1;
        let weakest = i;
        if (left < heap.length && worse(heap[left], heap[weakest])) weakest = left;
        if (right < heap.length && worse(heap[right], heap[weakest])) weakest = right;
        if (weakest === i) break;
        swap(i, weakest);
        i = weakest;
      }
    }
    return top;
  };
  for (const word of count.keys()) {
    push(word);
    if (heap.length > k) {
      pop();
    }
  }
  const result = [];
  while (heap.length > 0) {
    result.push(pop());
  }
  return result.reverse();
}

