function topKFrequent(words, k) {
  const tally = new Map();
  for (const w of words) tally.set(w, (tally.get(w) ?? 0) + 1);
  return [...tally.keys()]
    .sort((a, b) => tally.get(b) - tally.get(a) || (a < b ? -1 : a > b ? 1 : 0))
    .slice(0, k);
}

