function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abc';
  const poolSize = large ? int(20, 120) : int(1, 6);
  const pool = new Set();
  while (pool.size < poolSize) {
    const length = large ? int(1, 10) : int(1, 3);
    let word = '';
    for (let i = 0; i < length; i++) word += letters[int(0, letters.length - 1)];
    pool.add(word);
  }
  const list = [...pool];
  const n = large ? 500 : int(1, 10);
  // Squaring the roll makes early pool words common and later ones rare, so counts differ and also tie.
  const words = Array.from({ length: n }, () => list[Math.floor(rand() * rand() * list.length)]);
  const distinct = new Set(words).size;
  return [words, int(1, distinct)];
}
